// studio_off_simple.ino — BOOT: скан, GPIO4: вырубить всё, сразу и без церемоний
#include <WiFi.h>
#include <WiFiUdp.h>
#include <EEPROM.h>

const char* WIFI_SSIDS[] = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* WIFI_PASSS[] = { "23233010", "KIBERone", "KIBERone" };

const int TCP_PORT = 8085, UDP_PORT = 8086, BTN_SCAN = 0, BTN_OFF = 4;
const int MAX_PCS = 20, TCP_TIMEOUT = 150, EEPROM_SIZE = 512;

WiFiUDP udp;
String ips[MAX_PCS];
int ipCount = 0;

void connectTo(int idx) {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSIDS[idx], WIFI_PASSS[idx]);
  unsigned long t = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t < 15000) delay(500);
}

void saveIps() {
  EEPROM.begin(EEPROM_SIZE);
  EEPROM.write(0, ipCount);
  int a = 1;
  for (int i = 0; i < ipCount; i++) {
    for (unsigned int c = 0; c < ips[i].length(); c++) EEPROM.write(a++, ips[i][c]);
    EEPROM.write(a++, '\n');
  }
  EEPROM.commit();
}

void loadIps() {
  ipCount = 0;
  EEPROM.begin(EEPROM_SIZE);
  int n = min(EEPROM.read(0), MAX_PCS), a = 1;
  for (int i = 0; i < n; i++) {
    String cur = "";
    while (true) {
      char c = EEPROM.read(a++);
      if (c == '\n' || c == 0 || c == 255) break;
      cur += c;
    }
    if (cur.length()) ips[ipCount++] = cur;
  }
}

void scan() {
  udp.begin(UDP_PORT);
  for (int r = 0; r < 2; r++) {
    udp.beginPacket(IPAddress(255, 255, 255, 255), UDP_PORT);
    udp.print("SCAN");
    udp.endPacket();
    delay(80);
  }
  char buf[64];
  unsigned long t = millis();
  while (millis() - t < 2000) {
    int len = udp.parsePacket();
    if (len > 0) {
      udp.read(buf, min(len, 63));
      buf[len] = '\0';
      if (String(buf).startsWith("IAM:")) {
        String ip = udp.remoteIP().toString();
        bool have = false;
        for (int i = 0; i < ipCount; i++) if (ips[i] == ip) have = true;
        if (!have && ipCount < MAX_PCS) ips[ipCount++] = ip;
      }
    }
    delay(5);
  }
  udp.stop();
  saveIps();
}

void offAll() {
  for (int net = 0; net < 3; net++) {
    connectTo(net);
    for (int i = 0; i < ipCount; i++) {
      WiFiClient c;
      if (c.connect(ips[i].c_str(), TCP_PORT, TCP_TIMEOUT)) {
        c.print("OFF\n");
        c.stop();
      }
    }
  }
  connectTo(0);
}

void setup() {
  pinMode(BTN_SCAN, INPUT_PULLUP);
  pinMode(BTN_OFF, INPUT_PULLUP);
  loadIps();
  connectTo(0);
}

void loop() {
  if (digitalRead(BTN_SCAN) == LOW) scan();                 // BOOT — скан
  if (digitalRead(BTN_OFF) == LOW) offAll();                // GPIO4 — вырубить
  if (WiFi.status() != WL_CONNECTED) connectTo(0);
  delay(50);
}
